[grammar(u,'三64','首先…，然后…','Sequence intended actions','首先确认时间，然后报名 sets an order, not a claim that either step is finished. 其次 may introduce the next reason in an explanation; it is not automatically later in clock time.',[('首先确认时间，然后报名。','First confirm the time, then sign up.'),('首先听问题，然后回答。','First hear the question, then answer.'),('首先看来源，然后核对日期。','First check the source, then the date.')],('首先确认，然后报名，所以已经报名了。','这是顺序安排，还没说明报名完成。','A planned sequence is not a completion report.')),
grammar(u,'三65','并且 + 相关补充','Add a related point','并且 adds a related action or quality to the preceding clause. 她核对时间，并且问了地点 states two actions; it does not imply causation. Avoid using 并且 where the intended relation is a contradiction.',[('她核对时间，并且问了地点。','She checks the time and also asks the location.'),('活动有讲解，并且有练习。','The activity includes explanation and practice.'),('先听完，并且记下问题。','Hear everything first and also note questions.')],('她有空，并且她没有空。','她想来，但是没有空。','Use a contrastive connection for opposing information.'))],
